roots=[R('-gen-','Latin genus / gignere','生；种类','生む；種類','来自拉丁语 genus（种类、出身）和 gignere（生）。生出来 → generation；一个种类 → generic；同一种类 → homogeneous；本地生的 → indigenous。⚠️ congenial 与 gen 的关系不确定，别硬拆。','ラテン語 genus（種類・出身）と gignere（生む）から。生まれる → generation；種類 → generic；同じ種類 → homogeneous；その土地で生まれた → indigenous。congenial は語根との関係が不確かなので分解しない。',[w['w'] for w in gen if w['parts']]),
R('-cred-','Latin credere','相信','信じる','来自拉丁语 credere（相信）。可以信 → credible；不能信 → incredible；轻易信 → credulous；给予信任 → accredit。⚠️ creditable（值得称赞）≠ credible（可信）。','ラテン語 credere（信じる）から。信じられる → credible；信じがたい → incredible；すぐ信じる → credulous；信頼を与える → accredit。creditable（称賛に値する）≠ credible（信用できる）。',[w['w'] for w in cred]),
R('-rect- / -reg-','Latin regere / rectus','直；规则；统治','まっすぐ；規則；治める','来自拉丁语 regere（使笔直、统治）和 rectus（直的、正的）。引导 → direct / director；改正 → corrective；规则 → regular / regulatory；统治 → regime / regent。','ラテン語 regere（まっすぐにする・治める）と rectus（正しい）から。導く → direct / director；正す → corrective；規則 → regular / regulatory；治める → regime / regent。',[w['w'] for w in rect]),
R('-cur- / -curr- / -curs-','Latin currere','跑','走る','来自拉丁语 currere（跑）。朝你跑来 → occur；再跑回来 → recur；一起跑 → concurrent；匆匆跑过 → cursory；跑回求助 → recourse。','ラテン語 currere（走る）から。向かって走ってくる → occur；また走ってくる → recur；一緒に走る → concurrent；走り抜ける → cursory；駆け戻って頼る → recourse。',[w['w'] for w in cur])]
d=dict(day=52,date='2026-11-24',title_zh='四大词根 + 保险与理赔 + 宴会与活动布置',title_ja='4つの語根＋保険と保険金請求＋宴会とイベントの準備',
 intro_zh='今天的词根是 -gen-（生；种类）、-cred-（相信）、-rect- / -reg-（直；规则；统治）、-cur- / -curr-（跑）；主题是保险与理赔，以及宴会与活动布置。',
 intro_ja='今日の語根は -gen-（生む；種類）、-cred-（信じる）、-rect- / -reg-（まっすぐ；規則；治める）、-cur- / -curr-（走る）。テーマは保険と保険金請求、宴会とイベントの準備。',
 voice='en-US-AriaNeural',roots=roots,groups=G)
